class InventarisError(Exception):
    pass

class StokTidakCukup(InventarisError):
    def __init__(self, tersedia, diminta):
        self.tersedia = tersedia
        self.diminta = diminta
        super().__init__(f"Stok {tersedia}, permintaan {diminta}")

class Persediaan:
    def __init__(self, stok):
        if type(stok) is not int or stok < 0:
            raise ValueError("Stok harus integer >= 0")
        self._stok = stok

    @property
    def stok(self):
        return self._stok

    def keluarkan(self, jumlah):
        if type(jumlah) is not int or jumlah <= 0:
            raise ValueError("Jumlah harus integer positif")
        if jumlah > self.stok:
            raise StokTidakCukup(self.stok, jumlah)
        self._stok -= jumlah

barang = Persediaan(2)
try:
    barang.keluarkan(3)
except StokTidakCukup as error:
    print(error)
    print("Kekurangan:", error.diminta - error.tersedia)
except InventarisError:
